ChromaticIndexAtMost.tex_statement:
\begin{definition}
The chromatic index of a multihypergraph $\mathcal H$ is at most $q$ if
there exists a proper edge-coloring of $\mathcal H$ using colors from a
set of size $q$.
\end{definition}

ChromaticIndexAtMostReal.tex_statement:
\begin{definition}
For a multihypergraph $\mathcal H$ and a real number $x$, the assertion
$\chi'(\mathcal H)\le x$ means that there is a natural number $q\le x$ such
that $\mathcal H$ has a proper edge-coloring using at most $q$ colors.
\end{definition}

FiniteGraphGreedyColoring.tex_statement:
\begin{lemma}
Let $G$ be a finite simple graph and $q$ a positive natural number.
If every vertex has degree less than $q$, then there exists a coloring
$c:V(G)\to\{0,\ldots,q-1\}$ with $c(e)\ne c(f)$ whenever $e,f$ are adjacent.
\end{lemma}

FiniteProbabilityMass.tex_statement:
\begin{definition}
For a finite sample space $\Omega$, a probability mass function is a function
$\mu:\Omega\to\mathbb R$ such that $\mu(\omega)\ge 0$ for every
$\omega\in\Omega$ and $\sum_{\omega\in\Omega}\mu(\omega)=1$.
\end{definition}

HypergraphClass.tex_statement:
\begin{definition}
For natural numbers $k,t,D$, $H(k,t,D)$ denotes the class of
$k$-uniform, $t$-simple multihypergraphs with maximum degree at most $D$.
In Lean this is represented on fixed vertex and edge-index types.
\end{definition}

HypergraphDegree.tex_statement:
\begin{definition}
For a finite-edge multihypergraph $\mathcal H$ and a vertex $v$, the degree
$\deg_{\mathcal H}(v)$ is the number of edge indices $e\in E(\mathcal H)$
whose assigned edge contains $v$.
\end{definition}

IndependentPairCount.tex_statement:
\begin{definition}
For a finite simple graph $G$ and a vertex $v\in V(G)$, $P_G(v)$ is the
number of two-element subsets $S\subseteq N_G(v)$ that are independent in
$G$, meaning no two distinct vertices of $S$ are adjacent.
\end{definition}

IndependentTripleCount.tex_statement:
\begin{definition}
For a finite simple graph $G$ and a vertex $v\in V(G)$, $T_G(v)$ is the
number of three-element subsets $S\subseteq N_G(v)$ that are independent in
$G$, meaning no two distinct vertices of $S$ are adjacent.
\end{definition}

KPartiteFixedVertexCauchyEstimate.tex_statement:
\begin{helper}
Let $k$ be a natural number, fix a vertex $i\in\{1,\ldots,k\}$, and let
$w_{ab}\ge 0$ be a nonnegative real weight assigned to each ordered pair of
indices.  Let $S_i$ be the set of pairs $\{j,\ell\}$ with $j<\ell$ and
$j,\ell\ne i$.  Then
\[
\sum_{\{j,\ell\}\in S_i}\sqrt{w_{ij}w_{i\ell}w_{j\ell}}
\le
\left(\sum_{\{j,\ell\}\in S_i}w_{ij}w_{i\ell}\right)^{1/2}
\left(\sum_{\{j,\ell\}\in S_i}w_{j\ell}\right)^{1/2}.
\]
\end{helper}

KPartiteFixedVertexReducedEstimate.tex_statement:
\begin{helper}
Let $I$ be a finite nonempty linearly ordered index set.  Let
$(u_a)_{a\in I}$ and $(v_{ab})_{a,b\in I}$ be nonnegative real families.  Then
\[
\sum_{\substack{a<b\\a,b\in I}}\sqrt{u_a u_b v_{ab}}
\le
\left(\sum_{a\in I}u_a\right)
\sqrt{
\frac{|I|-1}{2|I|}
\sum_{\substack{a<b\\a,b\in I}}v_{ab}}.
\]
\end{helper}

KUniformKSimpleChromaticIndexBound.tex_statement:
\begin{theorem}
For each $\iota>0$ and $k\in\mathbb Z^+$, there is $D_0$ such that if
$D\ge D_0$ and $\mathcal H$ is a $k$-uniform $k$-simple hypergraph with
maximum degree at most $D$, then
\[
\chi'(\mathcal H)\le
\left(1-\frac{k-1}{2k^2}
+\frac{(k-1)(k-2)}{6k^3\sqrt{k}}+\iota\right)kD.
\]
\end{theorem}

LineGraphOfHypergraph.tex_statement:
\begin{definition}
The line graph $L(\mathcal H)$ of a multihypergraph $\mathcal H$ is the
simple graph whose vertices are the edge indices of $\mathcal H$, with two
distinct edge indices adjacent exactly when their assigned hyperedges
intersect.
\end{definition}

LocalBParameter.tex_statement:
\begin{definition}
For a finite simple graph $G$, an integer scale $M$, and a vertex
$v\in V(G)$, the local parameter is
\[
b_{G,M}(v)=\frac{\deg_G(v)}{M}
-\frac{P_G(v)}{M^2}
+\frac{T_G(v)}{M^3}.
\]
\end{definition}

LocalBParameterRealAntitone.tex_statement:
\begin{lemma}
Let $G$ be a finite simple graph and $v$ a vertex. If
$0<M\le N$ and $\deg_G(v)\le M$, then
$b^{\mathbb R}_{G,N}(v)\le b^{\mathbb R}_{G,M}(v)$.
\end{lemma}

LocalBParameterRealFloorTransfer.tex_statement:
\begin{lemma}
Let $H$ be a finite $k$-uniform hypergraph, where $k\ge1$.
If $r\ge1$ is real and all vertex degrees of $H$ are at most $r$, then,
for $n=\lfloor r\rfloor_+$ and every edge $e$,
\[
b^{\mathbb R}_{L(H),kr}(e)\le b_{L(H),kn}(e).
\]
\end{lemma}

LocalBParameterRealNatCast.tex_proof:
\begin{proof}
Substitute the real cast of $M$ into \noderef{LocalBParameterReal}.
The three terms are exactly those in \noderef{LocalBParameter}, including
when $M=0$. In particular this applies to the natural number $kn$, whose
real cast is the product of the real casts of $k$ and $n$.
\end{proof}

LocalBParameterRealNatCast.tex_statement:
\begin{lemma}
For every finite simple graph $G$, vertex $v$, and natural number $M$,
$b^{\mathbb R}_{G,M}(v)=b_{G,M}(v)$.
\end{lemma}

LocalBParameterStrictIncrease.tex_proof:
\begin{proof}
Regard all counts and $M,r$ as real numbers. Since $M>0$, division by
$M^2$ and $M^3$ preserves inequalities. Expanding the definition gives
\[
\begin{aligned}
b_{H,M}(w)-b_{G,M}(v)
&=\frac{1}{M}-\frac{P_H(w)-P_G(v)}{M^2}
  +\frac{T_H(w)-T_G(v)}{M^3}\\
&\ge\frac{1}{M}-\frac{r}{M^2}
 =\frac{M-r}{M^2}>0.
\end{aligned}
\]
The last inequality uses $r<M$ and $M^2>0$, proving the claim.
\end{proof}

MaxDegreeAtMost.tex_statement:
\begin{definition}
A multihypergraph $\mathcal H$ has maximum degree at most $D$ if
$\deg_{\mathcal H}(v)\le D$ for every vertex $v\in V(\mathcal H)$.
\end{definition}

NibbleBadEvent.lean_proof:
fun j => match j with
  | Sum.inl x => {ω | d < (NibbleResidualDegree H (NibbleSelectedEdges Q ω) x.val : ℝ)}
  | Sum.inr e => {ω | z ≤ ((NibbleDeletedColors H M (NibbleSelectedEdges Q ω) e).card : ℝ)}

NibbleCeilingPowerEstimate.tex_statement:
\begin{lemma}
Let $\iota,\gamma,\Delta$ be real numbers with $\gamma\ge1$, $\Delta\ge4$,
$e^{-\gamma}\le\min(1/4,\iota/8)$, $1/\gamma\le\iota/4$, and
$2/\Delta\le\iota/8$. Then
\[
\left(1-\frac{1-e^{-\gamma}}\Delta+\frac2{\Delta^2}\right)^{\lceil\Delta/\gamma\rceil}
\le 1-\frac{1-\iota/2}{\gamma}.
\]
\end{lemma}

NibbleDeletedColors.tex_statement:
\begin{definition}
The deleted-color set at $e$ for retained lists $M$ and selections $I$ is
$\operatorname{Del}_e(I)=\{a\in M(e):\exists f\in I_a,\ f\sim e\}$,
where adjacency is in the line graph of the hypergraph.
\end{definition}

NibbleInducedBParameterComparison.tex_statement:
\begin{lemma}
Let $G$ be a finite simple graph, $\Delta>0$ an integer, $s$ a subset of
its vertices and $r\in s$. If $\deg_G(r)\le\Delta$, then
$b_{G[s],\Delta}(r)\le b_{G,\Delta}(r)$.
\end{lemma}

NibbleRegularCompletionsExist.tex_statement:
\begin{lemma}
If $H$ has finite edge-index set, is $k$-uniform, and has maximum degree
at most $D$, then for any retained lists $M$ there exists a nibble
completion datum for $H,M,\Delta=kD$.
\end{lemma}

NibbleResidualDegree.tex_statement:
\begin{definition}
For finite edge-index set $E$, selections $I_a\subseteq E$, and a vertex
$x$, the residual-degree statistic is
$Y_x(I)=|\{e:x\in H(e),\ \forall a,\ e\notin I_a\}|$.
\end{definition}

NibbleSelectedEdges.tex_statement:
\begin{definition}
For a completion datum and an outcome, the selected original edges of
color $a$ are $I_a(\omega)=\{e:a\in M(e),\ j_a(e)\in J_a(\omega)\}$,
where $J_a$ is the completed selection. Edges outside the retained color
class cannot be selected with that color.
\end{definition}

OneUniformNonemptyIntersectionCard.tex_proof:
\begin{proof}
By \noderef{UniformHypergraph}, the edge $f$ has exactly one vertex.
The intersection $g\cap f$ is a subset of $f$, so it has at most one
vertex.  By hypothesis the intersection is nonempty, so it has at least
one vertex.  Therefore its cardinality is exactly one.
\end{proof}

OneUniformNonemptyIntersectionCard.tex_statement:
\begin{helper}
Let $\mathcal F$ be a $1$-uniform hypergraph.  For any two edge labels
$f$ and $g$, if $g\cap f$ is nonempty, then $|g\cap f|=1$.
\end{helper}

OrderThreeAffineIndependentPairs.tex_statement:
\begin{lemma}
For every $q\in\mathbb N$, the number of independent pairs in the
neighborhood of $\ast$ in $L(A_q)$ is $9q^2$.
\end{lemma}

OrderThreeAffineIndependentTriples.tex_statement:
\begin{lemma}
For every $q\in\mathbb N$, the number of independent triples in the
neighborhood of $\ast$ in $L(A_q)$ is $3q^3$.
\end{lemma}

PartialEdgeColoringGreedyFinish.tex_statement:
\begin{lemma}
Let $H$ be a finite $k$-uniform hypergraph and let $K,N$ be natural
numbers. Suppose $C\subseteq E(H)$ has a proper coloring with $K$ colors
and its canonical residual on $E(H)\setminus C$ has maximum degree at
most $N$. Then $H$ has a proper edge-coloring with $K+kN+1$ colors.
\end{lemma}

ProperEdgeColoring.tex_statement:
\begin{definition}
A coloring $c$ of the edge indices of a multihypergraph $\mathcal H$ is a
proper edge-coloring if any two distinct intersecting hyperedges receive
distinct colors.
\end{definition}

RandomIndependentSetSamplingGammaLeDelta.tex_statement:
\begin{lemma}
Let $G$ be a finite graph, let $\Delta$ be a positive integer, and let
$\gamma>0$.  If the activation--priority sampling law
\noderef{RandomIndependentSetSampling} exists on a nonempty vertex set with
activation probability $\gamma/\Delta$, then $\gamma\le \Delta$.
\end{lemma}

RealDegreeFloorBound.lean_statement:
theorem RealDegreeFloorBound {V E : Type*}
    [Fintype E] [DecidableEq E] [DecidableEq V]
    (H : MultiHypergraph V E) {r : ℝ}
    (hd : ∀ v, (HypergraphDegree H v : ℝ) ≤ r) :
    MaxDegreeAtMost H ⌊r⌋₊ := by

RealDegreeFloorBound.tex_proof:
\begin{proof}
Each degree in \noderef{HypergraphDegree} is a natural number. A natural
number at most $r$ is at most its natural floor. Applying this at every
vertex gives \noderef{MaxDegreeAtMost}.
\end{proof}

RealDegreeFloorBound.tex_statement:
\begin{lemma}
If every vertex degree of a finite hypergraph $H$ is at most a real number
$r$, then $H$ has maximum degree at most $\lfloor r\rfloor_+$, the
nonnegative natural floor of $r$.
\end{lemma}

SamplingBernoulliPrioritySubsetSum.tex_statement:
\begin{helper}
Let \(S\) be a finite set and let \(p,x\in\mathbb R\).  Then
\[
\sum_{B\subseteq S}p^{|B|}(1-p)^{|S|-|B|}x^{|B|}
=((1-p)+px)^{|S|}.
\]
\end{helper}

SamplingCopiedCommonTags.tex_statement:
\begin{lemma}
Let $V,W$ be finite sets, $\phi:V\to W$ injective, and $S\subseteq V$.
There exist a finite tag set $T$ and injections $s:V\to T$, $t:W\to T$
such that $s(v)=t(w)$ if and only if $v\in S$ and $\phi(v)=w$.
Every tag belongs to the image of $s$ or of $t$.
\end{lemma}

SamplingFiniteProductMatchedCoordinateEx.tex_statement:
\begin{helper}
Let two one-sided finite-coordinate extensions be computed from the same base
cell weight \(w_0\) under the same Bernoulli activation parameter \(p\).  On
the source side the extension factor is
\[
  p^{|A_D|}(1-p)^{|D|-|A_D|}
  \prod_v \begin{cases}t_v,&v\in K,\\1,&v\notin K,\end{cases}
\]
and on the target side the extension factor is the analogous expression with
primed finite data.  If the Bernoulli activation factors are equal and the
priority lower-cut products are equal, then the two normalized extension
weights are equal.
\end{helper}

SamplingFixedPairChamberSurvival.tex_statement:
\begin{helper}
Let $G$ be a $\Delta$-regular graph and let $I$ be sampled from
\noderef{RandomIndependentSetSampling} with parameter $\gamma$.  Fix
$r$ and $X\subseteq N_G(r)$, and assume that no two distinct vertices of
$X$ have a common neighbor outside $N_G[r]$.  If $u,v\in X$ are distinct
and non-adjacent, then, writing
$c_{uv}=|N_G(u)\cap N_G(v)|$,
\[
\Pr[u\in I\hbox{ and }v\in I]
=
\frac{2}{\Delta^2}
\int_{0\le x\le y\le\gamma}
\left(1-\frac{x}{\Delta}\right)^{\Delta-c_{uv}}
\left(1-\frac{y}{\Delta}\right)^\Delta\,dy\,dx .
\]
\end{helper}

SamplingInducedNeighborhoodLocalBParamet.lean_statement:
noncomputable def SamplingInducedNeighborhoodLocalBParameter {V : Type*}
    [Fintype V] [DecidableEq V] (G : SimpleGraph V) [DecidableRel G.Adj]
    (Delta : ℕ) (r : V) (X : Finset V) : ℝ :=

SamplingInducedNeighborhoodLocalBParamet.tex_statement:
\begin{definition}
For a graph $G$, a vertex $r$, a finite set $X$, and a scale $\Delta$, define
the induced-neighborhood bookkeeping expression by
\[
\frac{|X|}{\Delta}
-\frac{|\mathcal J_2(X)|}{\Delta^2}
+\frac{|\mathcal J_3(X)|}{\Delta^3},
\]
where $\mathcal J_2(X)$ and $\mathcal J_3(X)$ are the independent two- and
three-element subsets of $X$.  The vertex $r$ is a parameter carried for the
downstream induced-neighborhood application; it does not otherwise affect the
value of this expression.
\end{definition}

SamplingOneCoordinateChamberFiberVolume.tex_statement:
\begin{helper}
Let \(V\) be finite, let \(v\in V\), and let \(B\subseteq V\setminus\{v\}\).
For \(0\le a\le 1\), the Lebesgue measure of the fiber
\[
\{r\in \mathbb R^{V\setminus\{v\}}: 0\le r(w)\le 1\text{ for all }w,\ 
r(z)<a\text{ for all }z\in B\}
\]
is \(a^{|B|}\).
\end{helper}

SamplingOneCoordinateComplementMeasurePr.tex_statement:
\begin{helper}
Let \(V\) be a finite vertex set and fix \(v\in V\).  The coordinate-splitting
map
\[
q\longmapsto \bigl(q(v),(q(w))_{w\ne v}\bigr)
\]
from \(\mathbb R^V\) to \(\mathbb R\times\mathbb R^{V\setminus\{v\}}\)
preserves Lebesgue product measure.
\end{helper}

SamplingOneVertexActivationIntegralSum.tex_statement:
\begin{helper}
Fix a finite simple graph $G$, a vertex $v$, a regularity value $\Delta$ with
every vertex having degree $\Delta$, and a sampling parameter $\gamma$.  Then
\[
\begin{aligned}
&\sum_{A\subseteq V(G)}{\bf 1}_{v\in A}
\left(\frac{\gamma}{\Delta}\right)^{|A|}
\left(1-\frac{\gamma}{\Delta}\right)^{|V(G)|-|A|}
\int_0^1 a^{|\{u:u\in A,\ u\sim_G v\}|}\,da  \\
&\qquad =
\frac{\gamma}{\Delta}
\int_0^1
\left(1-\frac{\gamma}{\Delta}(1-a)\right)^\Delta\,da .
\end{aligned}
\]
\end{helper}

SamplingOneVertexComparisonPartition.tex_statement:
\begin{helper}
Let $G$ be a finite graph, let $\nu$ be a probability measure on
activation--priority pairs $(A,\pi)$, and fix a vertex $v$.  Assume first
that each activation atom has full measure on its priority cube:
\[
\nu\{(A,\pi): A=A_0,\ \pi(u)\in[0,1]\hbox{ for every }u\in A_0\}
=\nu\{(A,\pi):A=A_0\}
\]
for every activation set $A_0$.  Assume also that, whenever $v\in A_0$,
\[
\begin{aligned}
&\nu\{(A,\pi):A=A_0,\ \pi(u)\in[0,1]\hbox{ for every }u\in A_0,\\
&\hspace{4.5cm}
\pi(u)<\pi(v)\hbox{ for every }u\in A_0\cap N_G(v)\}\\
&=\nu\{(A,\pi):A=A_0\}\,
\operatorname{ofReal}\!\left(\int_0^1
a^{|\{u:u\in A_0,\ u\sim_G v\}|}\,da\right).
\end{aligned}
\]
Then the raw event that $v$ survives the priority comparison has measure
\[
\sum_{A_0}
{\bf 1}_{v\in A_0}\,
\nu\{(A,\pi):A=A_0\}\,
\operatorname{ofReal}\!\left(\int_0^1
a^{|\{u:u\in A_0,\ u\sim_G v\}|}\,da\right).
\]
\end{helper}

SamplingOneVertexPrioritySliceExact.tex_statement:
\begin{helper}
Fix a finite vertex set \(V\), a graph \(G\) on \(V\), a measure \(\nu\) on
\(\operatorname{Finset}(V)\times \mathbb R^V\), an activation set \(A\), a
vertex \(v\), and real numbers \(0\le a\le b\le 1\).  Assume the lower-rectangle
law
\[
\nu\{\omega:\omega_1=A\text{ and }0\le \omega_2(u)\le t(u)\text{ for all }u\}
=
\nu\{\omega:\omega_1=A\}\operatorname{ofReal}\Bigl(\prod_{u\in V}t(u)\Bigr)
\]
for every \(t:V\to[0,1]\).  Assume also that
\(\nu\{\omega:\omega_1=A\}\) is finite.  Then
\[
\begin{aligned}
&\nu\{\omega:\omega_1=A,\ a<\omega_2(v)\le b,\text{ and for every }u,\,
0\le \omega_2(u)\le b\text{ if }u=v,\\
&\hspace{35mm}
0\le \omega_2(u)\le a\text{ if }u\in A\text{ and }uv\in E(G),\text{ and }
0\le \omega_2(u)\le1\text{ otherwise}\}\\
&=
\nu\{\omega:\omega_1=A\}\operatorname{ofReal}
\bigl(b\,a^{|\{u\in A:uv\in E(G)\}|}\bigr)
-
\nu\{\omega:\omega_1=A\}\operatorname{ofReal}
\bigl(a\,a^{|\{u\in A:uv\in E(G)\}|}\bigr).
\end{aligned}
\]
\end{helper}

SamplingPairExposureEstimate.tex_statement:
\begin{lemma}
Let $G$ be a $\Delta$-regular graph, let $I$ be sampled by
\noderef{RandomIndependentSetSampling} with parameter $\gamma$, fix a vertex
$r$, and let $X\subseteq N_G(r)$.  Assume that no two distinct vertices of
$X$ have a common neighbor outside $N_G[r]$.  Let $\mathcal J_2$ be the
independent pairs in $X$.  For $uv\in\mathcal J_2$, put
$c_{uv}=|N_G(u)\cap N_G(v)|$.  Then
\[
\mathbb E\binom{|I\cap X|}{2}
=
\sum_{uv\in\mathcal J_2}
\frac{2}{\Delta^2}
\int_{0\le x\le y\le\gamma}
\left(1-\frac{x}{\Delta}\right)^{\Delta-c_{uv}}
\left(1-\frac{y}{\Delta}\right)^\Delta\,dy\,dx .
\]
\end{lemma}

SamplingPairTripleBonferroniCore.tex_statement:
\begin{lemma}
For every $\eta>0$ there are $\Delta_0$ and $\gamma_0$ such that the
following holds.  Let $G$ be a $\Delta$-regular graph with
$\Delta\ge\Delta_0$, let $\gamma\ge\gamma_0$, and let $I$ be sampled by
\noderef{RandomIndependentSetSampling}.  Fix $r$ and
$X\subseteq N_G(r)$, and assume that no two distinct vertices of $X$ have a
common neighbor outside $N_G[r]$.  If $\mathcal J_2$ and $\mathcal J_3$ are
the independent pairs and independent triples in $X$, then
\[
\mathbb E\binom{|I\cap X|}{2}
-\mathbb E\binom{|I\cap X|}{3}
\ge
\frac{|\mathcal J_2|}{\Delta^2}
-\frac{|\mathcal J_3|}{\Delta^3}
-\eta .
\]
\end{lemma}

SamplingPriorityProjectionVolumeNull.tex_statement:
\begin{helper}
Let \(V\) be finite, and let \(\nu\) be a measure on
\(\mathcal P(V)\times\mathbb R^V\), equipped with the product of the discrete
activation sigma-algebra and the Borel priority sigma-algebra.
Suppose every activation atom \(F_A=\{(B,q):B=A\}\) has finite mass, and
for every \(A\subseteq V\) and \(t:V\to[0,1]\),
\[
\nu\{(B,q):B=A,\ 0\le q(x)\le t(x)\text{ for all }x\in V\}
=\nu(F_A)\operatorname{ofReal}\!\left(\prod_{x\in V}t(x)\right).
\]
If \(D\subseteq\mathbb R^V\) is Borel measurable and has Lebesgue volume
zero, then \(\nu\{(B,q):q\in D\}=0\).
\end{helper}

SamplingSimplexIndicatorLIntegralRestric.tex_statement:
\begin{helper}
Let \(g:\mathbb R^3\to\mathbb R\) be continuous.  Then the all-real iterated
nonnegative integral of the simplex indicator equals the nested
nonnegative integral over the ordered simplex:
\[
\int_{\mathbb R}^{+}\int_{\mathbb R}^{+}\int_{\mathbb R}^{+}
\mathbf 1_{\{0\le x\le y\le z\le1\}}
\operatorname{ofReal}(g(x,y,z))\,dz\,dy\,dx
=
\int_{(0,1]}^{+}\int_{(0,z]}^{+}\int_{(0,y]}^{+}
\operatorname{ofReal}(g(x,y,z))\,dx\,dy\,dz .
\]
\end{helper}

SamplingThreeCoordinateComplementMeasure.tex_statement:
\begin{helper}
Let \(V\) be finite and let \(a,b,c\in V\) be pairwise distinct.  The map
\[
q\in\mathbb R^V\longmapsto
\bigl(q_a,q_b,q_c,(q_v)_{v\in V\setminus\{a,b,c\}}\bigr)
\in \mathbb R^3\times\mathbb R^{V\setminus\{a,b,c\}}
\]
preserves finite product Lebesgue measure.
\end{helper}

SamplingTripleActivationChamberSum.tex_statement:
\begin{helper}
Let $G$ be a finite graph, let $\mu$ be an activation--priority sample with
activation probability $\gamma/\Delta$ as in
\noderef{RandomIndependentSetSampling}, and assume $\Delta>0$.  Fix three
distinct vertices $a,b,c$, put $Q=\{a,b,c\}$, and consider the ordered chamber
\[
0\le z\le y\le x\le \gamma
\]
corresponding to $x=\gamma(1-\pi(a))$, $y=\gamma(1-\pi(b))$, and
$z=\gamma(1-\pi(c))$.  For an activation set $A\supseteq Q$, let the three
atomwise exponents be
\[
|\{w\in A\setminus Q:w\sim a\}|,
\quad
|\{w\in A\setminus Q:w\not\sim a,\ w\sim b\}|,
\quad
|\{w\in A\setminus Q:w\not\sim a,\ w\not\sim b,\ w\sim c\}|.
\]
Then the finite sum over activation atoms of the Bernoulli atom weight times
the corresponding ordered-chamber integral is exactly
\[
\begin{aligned}
&\sum_{A\supseteq Q}
\left(\frac{\gamma}{\Delta}\right)^{|A|}
\left(1-\frac{\gamma}{\Delta}\right)^{|V(G)|-|A|}
\frac1{\gamma^3}
\int_{0\le z\le y\le x\le\gamma}
\left(1-\frac{x}{\gamma}\right)^{|\{w\in A\setminus Q:w\sim a\}|} \\
&\qquad\qquad\qquad\qquad\cdot
\left(1-\frac{y}{\gamma}\right)^{|\{w\in A\setminus Q:w\not\sim a,\ w\sim b\}|}
\left(1-\frac{z}{\gamma}\right)^{|\{w\in A\setminus Q:w\not\sim a,\ w\not\sim b,\ w\sim c\}|}
\,dx\,dy\,dz  \\
&=
\frac1{\Delta^3}
\int_{0\le z\le y\le x\le\gamma}
\left(1-\frac{x}{\Delta}\right)^{|\{w\in V(G)\setminus Q:w\sim a\}|}
\left(1-\frac{y}{\Delta}\right)^{|\{w\in V(G)\setminus Q:w\not\sim a,\ w\sim b\}|} \\
&\qquad\qquad\qquad\qquad\cdot
\left(1-\frac{z}{\Delta}\right)^{|\{w\in V(G)\setminus Q:w\not\sim a,\ w\not\sim b,\ w\sim c\}|}
\,dx\,dy\,dz .
\end{aligned}
\]
\end{helper}

SamplingTripleChamberAffineIntegralIdent.tex_statement:
\begin{helper}
Let \(\gamma>0\), and let \(S_x,S_y,S_z\) be finite sets.  Then
\[
\int_0^1\int_0^z\int_0^y
x^{|S_x|}y^{|S_y|}z^{|S_z|}\,dx\,dy\,dz
=
\frac1{\gamma^3}\int_0^\gamma\int_z^\gamma\int_y^\gamma
\left(1-\frac{x}{\gamma}\right)^{|S_x|}
\left(1-\frac{y}{\gamma}\right)^{|S_y|}
\left(1-\frac{z}{\gamma}\right)^{|S_z|}\,dx\,dy\,dz .
\]
\end{helper}

SamplingTripleCubeChamberIntegralFromLow.tex_statement:
\begin{helper}
Let \(V\) be finite, let \(\nu\) be a measure on
\(\operatorname{Finset}(V)\times\mathbb R^V\), and fix an activation fiber
\(A\).  Assume the lower-rectangle law on this fiber: for every
\((t_v)_{v\in V}\in[0,1]^V\),
\[
\nu\{\omega_1=A,\ 0\le \pi(v)\le t_v\text{ for all }v\}
=\nu\{\omega_1=A\}\operatorname{ofReal}\Bigl(\prod_{v\in V} t_v\Bigr).
\]
Let \(\gamma>0\), let \(a,b,c\in V\) be pairwise distinct, and let
\(S_x,S_y,S_z\subseteq V\) be pairwise disjoint and disjoint from
\(\{a,b,c\}\).  Assume also that the fiber has finite mass.  Then the
measure of the bounded chamber event
\[
\begin{aligned}
\{\omega:\;&\omega_1=A,\quad
  \pi_\omega(a)\le \pi_\omega(b)\le \pi_\omega(c),\\
&\text{for every }w\in S_x,\ \pi_\omega(w)<\pi_\omega(a),\\
&\text{for every }w\in S_y,\ \pi_\omega(w)<\pi_\omega(b),\\
  \text{ and for every }w\in S_z,\ \pi_\omega(w)<\pi_\omega(c)\}
  \cap \{\omega:\pi_\omega(v)\in[0,1]\text{ for every }v\in V\}
\end{aligned}
\]
is at most the displayed ordered integral:
\[
\nu[\omega_1=A]\operatorname{ofReal}\left(
\frac{1}{\gamma^3}
\int_{0\le z\le y\le x\le\gamma}
\left(1-\frac{x}{\gamma}\right)^{|S_x|}
\left(1-\frac{y}{\gamma}\right)^{|S_y|}
\left(1-\frac{z}{\gamma}\right)^{|S_z|}\,dx\,dy\,dz\right).
\]
\end{helper}

SamplingTripleExpectationByIndependentTr.tex_statement:
\begin{helper}
Let $G$ be a finite graph, let $X\subseteq V(G)$, and let $\mu$ be a real
weight on subsets of $V(G)$.  Assume every set $S$ with $\mu(S)\ne0$ is
independent in $G$.  Let $\mathcal J_3$ be the family of three-element
independent subsets of $X$.  Then
\[
\sum_S \mu(S)\binom{|S\cap X|}{3}
=\sum_{Q\in\mathcal J_3}\sum_{S:Q\subseteq S}\mu(S).
\]
\end{helper}

SaturatedEdgeStructure.tex_statement:
\begin{lemma}
Let $\mathcal H$ be a $3$-uniform $2$-simple hypergraph of maximum degree at
most $D$, and let $e\in E(\mathcal H)$ intersect exactly $3(D-1)$ other
edges.  Put
\[
X(e,\mathcal H)=
\left(\bigcup\{h\in E(\mathcal H):h\cap e\ne\emptyset\}\right)\setminus e
\]
and, for $v\in e$ and $x\in X(e,\mathcal H)$, let
$\deg_{\mathcal H}(v,x)$ be the number of edges containing both $v$ and $x$.
Then:
\begin{enumerate}
\item every edge $h\ne e$ satisfies $|h\cap e|\le 1$;
\item for every $x\in X(e,\mathcal H)$,
$\sum_{v\in e}\deg_{\mathcal H}(v,x)\le D$;
\item for every $v\in e$,
$\sum_{x\in X(e,\mathcal H)}\deg_{\mathcal H}(v,x)=2(D-1)$.
\end{enumerate}
\end{lemma}

SubhypergraphOf.tex_statement:
\begin{definition}
Let $H'$ and $H$ be multihypergraphs on the same vertex type, with edge-index
types $F$ and $E$, respectively. We call $H'$ a sub-hypergraph of $H$ if
there exists an injective map $i:F\to E$ such that
$H'.\mathrm{edge}(f)=H.\mathrm{edge}(i(f))$ for every $f\in F$.
Thus inclusion preserves edge multiplicities: distinct child edge indices
use distinct ambient edge indices. Parallel ambient edges are allowed;
the ambient edge-to-vertex-set map need not be injective.
\end{definition}

TSimpleHypergraph.tex_statement:
\begin{definition}
A multihypergraph $\mathcal H$ is $t$-simple if every two distinct edge
indices $e,f\in E(\mathcal H)$ have intersection size at most $t$:
$|e\cap f|\le t$.
\end{definition}

TableColumnPairSquareBound.tex_statement:
\begin{helper}
Let $k\in\mathbb N$ with $k\ge2$, and let $x_1,\ldots,x_k$ be real
numbers.  Then
\[
\sum_{1\le i<i'\le k}x_ix_{i'}
\le {k-1\over 2k}\left(\sum_{i=1}^k x_i\right)^2 .
\]
\end{helper}

TablePairFillingBound.tex_statement:
\begin{lemma}
Let $k,n\in\mathbb N$ with $k\ge2$, let $C,T>0$, and let
$A=(a_{i,j})$ be a nonnegative $k\times n$ real table.  Suppose every column
sum is at most $C$ and the total table sum is at most $T$.  Put
$q=\lfloor T/C\rfloor$ and $r=T-qC$.  Then
\[
\sum_{j=1}^n\sum_{1\le i<i'\le k}a_{i,j}a_{i',j}
\le \frac{k-1}{2k}(qC^2+r^2).
\]
\end{lemma}

ThreeByNMatrixBound.tex_statement:
\begin{lemma}
Let $n\ge 3$, and let $A=(a_{i,j})_{i\in[3],j\in[n]}$ be a $3\times n$
matrix with entries in $[0,1]$.  Put $c_j=\sum_{i=1}^3 a_{i,j}$.  Suppose
$c_j\le 1$ for every $j$, $\sum_{j=1}^n c_j\le 3$, and
$1\ge c_1\ge c_2\ge\cdots\ge c_n$.  Then
\[
\frac{1}{9}\sum_{j=1}^{n}\sum_{1\le i<i'\le3}a_{i,j}a_{i',j}
+\frac{1}{27}\operatorname{perm}(A_{[3]})
-\frac{1}{27}\sum_{i=1}^3\sum_{j=1}^3a_{i,j}
\le \frac{2}{3^5},
\]
where $A_{[3]}$ is the leading $3\times3$ submatrix.
\end{lemma}

ThreeUniformSaturatedEdgeStructure.tex_statement:
\begin{lemma}
Let $\mathcal H$ be a $3$-uniform hypergraph of maximum degree at most $D$,
and let $e\in E(\mathcal H)$ intersect exactly $3(D-1)$ other edges.  Put
\[
X(e,\mathcal H)=
\left(\bigcup\{h\in E(\mathcal H):h\cap e\ne\emptyset\}\right)\setminus e
\]
and let $\deg_{\mathcal H}(v,x)$ denote the number of edges containing both
$v\in e$ and $x\in X(e,\mathcal H)$.  Then:
\begin{enumerate}
\item every edge $h\ne e$ satisfies $|h\cap e|\le1$;
\item for every $x\in X(e,\mathcal H)$,
$\sum_{v\in e}\deg_{\mathcal H}(v,x)\le D$;
\item for every $v\in e$,
$\sum_{x\in X(e,\mathcal H)}\deg_{\mathcal H}(v,x)=2(D-1)$.
\end{enumerate}
\end{lemma}

ThreeUniformT2OrientedIncidenceBound.tex_statement:
\begin{lemma}
In a $3$-uniform $3$-simple local extremal setup $S$ at scale $D$,
\[
\sum_{g\in V_2}\sigma(g)\ge2w(X_b)-D|V_1|.
\]
\end{lemma}

ThreeUniformThreeSimpleBalancedBigDegree.tex_statement:
\begin{lemma}
In a $3$-uniform $3$-simple local extremal setup at scale $D$, assume
$|X_b|=6$ and $w(X_b)\ge(2-\delta)D^2$.  Then every $g\in V_2$ satisfies
\[
\sum_{x\in g\setminus f}\sum_{v\in f\setminus g}
\deg_{\mathcal F}(v,x)
=\left(\frac43\pm\sqrt{\frac83\delta}\right)D .
\]
\end{lemma}

ThreeUniformTwoSimpleEventualNumericalEr.tex_statement:
\begin{lemma}
For every $\eta>0$ there is a natural number $D_0$ such that for every
integer $D\ge D_0$, putting $t=D^{-1/3}$ and $r=1+18t$, one has
\[
\frac29t+\frac8{9D}+r^3\frac2{3^5}
 +\frac{(r^2-1)r}{9}\le\frac2{3^5}+\eta.
\]
\end{lemma}

ThreeUniformTwoSimpleFreshEdgePreservesC.tex_statement:
\begin{helper}
Let $H\in H(3,2,D)$ and let $v$ have degree less than $D$.
The hypergraph obtained by adding two fresh vertices and one edge consisting
of those vertices and $v$, as in \noderef{KUniformFreshEdgeHypergraph},
belongs to $H(3,2,D)$.
\end{helper}

ThreeUniformTwoSimpleMatrixRescaling.tex_statement:
\begin{lemma}
Let $r,Q,P,L$ be real numbers with $r\ge1$, $Q\ge0$, and $L\le3$.
If $Q/9+P/27-L/27\le2/3^5$, then
\[
\frac{r^2Q}{9}+\frac{r^3P}{27}-\frac{rL}{27}
\le r^3\frac{2}{3^5}+\frac{(r^2-1)r}{9}.
\]
\end{lemma}

TriangleCountPartite.tex_statement:
\begin{lemma}
A tripartite graph with $m$ edges has at most $(m/3)^{3/2}$ triangles.
\end{lemma}

UniformHypergraph.tex_statement:
\begin{definition}
A multihypergraph $\mathcal H$ is $k$-uniform if every edge of
$\mathcal H$ contains exactly $k$ vertices.
\end{definition}

UniformHypergraphGreedyColoring.tex_statement:
\begin{lemma}
For positive natural numbers $k,n$, a finite $k$-uniform hypergraph of
maximum degree at most $n$ admits a proper edge-coloring with $kn$ colors.
\end{lemma}

UniformHypergraphLineDegreeBound.lean_statement:
theorem UniformHypergraphLineDegreeBound {V E : Type*}
    [Fintype E] [DecidableEq E] [DecidableEq V]
    (H : MultiHypergraph V E) [DecidableRel (LineGraphOfHypergraph H).Adj] {k n : ℕ}
    (hu : UniformHypergraph H k) (hd : MaxDegreeAtMost H n) (e : E) :
    (LineGraphOfHypergraph H).degree e ≤ k * (n - 1) := by

UniformHypergraphLineDegreeBound.tex_statement:
\begin{lemma}
If $H$ is a finite $k$-uniform hypergraph with maximum degree at most the
natural number $n$, then every edge $e$ has degree at most $k(n-1)$ in
$L(H)$, where subtraction in $n-1$ is natural subtraction.
\end{lemma}
